content.text:
请对以下 case 进行三维加权评分。

=== case_id ===
Case-04-focus-004

=== 用户原始指令 (query.txt) ===
帮我做个卡片,显示专注5小时18分钟,点开能看日程和完成情况

=== TaskSpec 契约 (task.taskSpec.json) ===
{
  "userQuery": "帮我做个卡片,显示专注5小时18分钟,点开能看日程和完成情况",
  "size": "2x4",
  "eventCandidates": [
    {
      "call": "clickToDeeplink",
      "args": {
        "bundleName": "com.huawei.hmos.settings",
        "abilityName": "com.huawei.hmos.settings.MainAbility",
        "uri": "intelligent_scene_entry"
      }
    }
  ],
  "dataModelSchema": {
    "data": {
      "focus": {
        "title": {
          "type": "string",
          "description": "专注模式卡片标题",
          "sampleValue": "专注模式"
        },
        "durationText": {
          "type": "string",
          "description": "当前累计专注时长展示文本",
          "sampleValue": "5小时18分钟"
        },
        "durationHourText": {
          "type": "string",
          "description": "当前累计专注时长的小时部分",
          "sampleValue": "5小时"
        },
        "durationMinuteText": {
          "type": "string",
          "description": "当前累计专注时长的分钟部分",
          "sampleValue": "18分钟"
        },
        "completionSummary": {
          "type": "string",
          "description": "专注与日程完成情况摘要",
          "sampleValue": "今日完成 4/5"
        },
        "statusText": {
          "type": "string",
          "description": "当前专注状态短文本",
          "sampleValue": "保持中"
        },
        "actionText": {
          "type": "string",
          "description": "打开专注详情的短入口文案",
          "sampleValue": "查看详情"
        }
      },
      "calendar": {
        "items": {
          "type": "array",
          "description": "今日日程列表",
          "sampleValue": [
            {
              "entityId": "calendar_event_001",
              "title": "项目复盘",
              "dtStart": "14:00",
              "dtEnd": "15:00"
            },
            {
              "entityId": "calendar_event_002",
              "title": "整理计划",
              "dtStart": "16:30",
              "dtEnd": "17:00"
            }
          ],
          "items": {
            "type": "object",
            "description": "日程项",
            "properties": {
              "entityId": {
                "type": "string",
                "description": "日程唯一标识符",
                "sampleValue": "calendar_event_001"
              },
              "title": {
                "type": "string",
                "description": "日程标题",
                "sampleValue": "项目复盘"
              },
              "dtStart": {
                "type": "string",
                "description": "日程开始时间",
                "sampleValue": "14:00"
              },
              "dtEnd": {
                "type": "string",
                "description": "日程结束时间",
                "sampleValue": "15:00"
              }
            }
          }
        }
      }
    }
  },
  "assetCandidates": [
    {
      "src": "resources/base/media/icon_focus.png",
      "description": "专注模式图标，适合用于专注时长或专注状态的视觉识别。"
    },
    {
      "src": "resources/base/media/icon_schedule.png",
      "description": "日程图标，适合用于今日安排、日程入口或日历事件摘要。"
    }
  ]
}

