eader","schedule_row_1","schedule_row_2","action_button"],"itemMargin":4,"styles":{"width":110,"height":110,"padding":6,"borderRadius":16,"backgroundColor":"#19000000","justifyContent":"start","alignItems":"start"}},{"id":"schedule_header","component":"Row","children":["schedule_icon","schedule_title"],"itemMargin":4,"styles":{"width":98,"height":18,"alignItems":"center"}},{"id":"schedule_icon","component":"Image","src":"resources/base/media/icon_schedule.png","styles":{"width":16,"height":16,"objectFit":"contain"}},{"id":"schedule_title","component":"Text","content":"今日日程","styles":{"width":78,"height":18,"fontSize":12,"fontWeight":700,"fontColor":"#E5000000","maxLines":1}},{"id":"schedule_row_1","component":"Text","content":"{{ ${/data/calendar/items/0/dtStart} + ' ' + ${/data/calendar/items/0/title} }}","styles":{"width":98,"height":18,"fontSize":12,"fontWeight":500,"fontColor":"#E5000000","maxLines":1}},{"id":"schedule_row_2","component":"Text","content":"{{ ${/data/calendar/items/1/dtStart} + ' ' + ${/data/calendar/items/1/title} }}","styles":{"width":98,"height":18,"fontSize":12,"fontWeight":400,"fontColor":"#99000000","maxLines":1}},{"id":"action_button","component":"Button","label":"{{ ${/data/focus/actionText} }}","onClick":[{"call":"clickToDeeplink","args":{"bundleName":"com.huawei.hmos.settings","abilityName":"com.huawei.hmos.settings.MainAbility","uri":"intelligent_scene_entry"}}],"styles":{"width":98,"height":32,"fontSize":14,"fontWeight":"medium","fontColor":"#FFFFFFFF","backgroundColor":"#564AF7","borderRadius":16}}]}}
